<!-- interior-advantages -->
<section class="interior-advantages">
    <div class="container">
        <div class="interior-advantages__content">
            <div class="interior-advantages__image fade-in">
                <picture>
                    <source srcset="img/default.png" data-srcset="img/interior-advantages/main.webp 1x, img/interior-advantages/main@2x.webp 2x" type="image/webp">
                    <source srcset="img/default.png" data-srcset="img/interior-advantages/main.jpg 1x, img/interior-advantages/main@2x.jpg 2x" type="image/jpeg">
                    <img class="lazyload" src="img/default.png" data-srcset="img/interior-advantages/main.jpg 1x, img/interior-advantages/main@2x.jpg 2x" alt="img">
                </picture>
            </div>
            <div class="interior-advantages__columns">
                <div class="head-content fade-in-up">
                    <h2 class="title title--h2">Интерьер <br>как&nbsp;продолжение <br>архитектуры</h2>
                    <div class="subtitle"><p>Мы&nbsp;создаём интерьеры загородных домов и&nbsp;резиденций класса люкс, <br>где каждая деталь гармонично дополняет архитектурный замысел.</p></div>
                </div>
                <div class="stats">
                    <div class="stats__item fade-in-up">
                        <div class="stats__value">15+</div>
                        <div class="stats__label">Лет опыта <br>в&nbsp;premium-сегменте</div>
                    </div>
                    <div class="stats__item fade-in-up">
                        <div class="stats__value">120+</div>
                        <div class="stats__label">Реализованных <br>интерьеров</div>
                    </div>
                    <div class="stats__item fade-in-up">
                        <div class="stats__value">500+ м<sup>2</sup></div>
                        <div class="stats__label">Средняя площадь <br>проекта</div>
                    </div>
                    <div class="stats__item fade-in-up"> 
                        <div class="stats__value">99%</div>
                        <div class="stats__label">Клиентов <br>рекомендуют нас</div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</section>